#[test]
fn only_the_copyable_phone_url_contains_the_session_access_token() {
    let (server, _requests) =
        RemoteAiStudioServer::start(egui::Context::default()).expect("server");
    let token = server.access_token.clone();
    let copied = server
        .phone_url("https://my-pc.example.ts.net")
        .expect("copyable phone URL");
    let displayed = masked_phone_url("https://my-pc.example.ts.net")
        .expect("displayed phone URL");
    assert!(copied.contains(&token));
    assert!(!displayed.contains(&token));
    assert!(displayed.contains(PHONE_URL_TOKEN_MASK));
    assert_ne!(copied, displayed);
}
